#
# trunk-verdict-holder.sh — У ВЕРДИКТА СТВОЛА ПОЯВЛЯЕТСЯ ЧИТАТЕЛЬ
# (задача PRO-Robotech/kaname#62).
#
# ─────────────────────────────────────────────────────────────────────────────
# ПРЕДМЕТ
#
# Ствол службы был красен процессом `ci` ДВА ВЛИВАНИЯ ПОДРЯД, и ни один запрос
# слияния этого не показал. Красное на стволе не читалось никем: перечень
# прогонов смотрят по одному, и первый в списке — не вердикт линии, а последнее
# событие (публикация образа с тем же успехом).
#
# Запрос слияния этого класса НЕ ЛОВИТ BY CONSTRUCTION: проверки идут на
# merge-ревизии, где история ветки цела, а после схлопывания она исчезает —
# свойства, зависящие от вхождения коммита в историю, меняют вердикт на
# противоположный. Перечень таких свойств здесь НЕ ВЫПИСЫВАЕТСЯ: его держит
# ведомость `vertexLedger` гейта `TestHistoryQuestionsAreAskedOfTheTrunk`
# (`internal/check/history_question_vertex_test.go`), и выписанная копия
# разошлась бы с нею молча.
#
# ─────────────────────────────────────────────────────────────────────────────
# ЧТО ЭТОТ ФАЙЛ ДЕЛАЕТ И ЧЕГО НЕ ДЕЛАЕТ
#
# Делает одно: по исходам заданий ствола решает, ОБЯЗАНО ли событие быть, и
# производит его — заводит либо дополняет держателя в трекере. Держатель именно
# в трекере, а не в уведомлении: уведомление прочитывают один раз и теряют, а
# открытая задача переживает смену сессии и не закрывается сама.
#
# НЕ делает: не судит код, не читает логи, не решает, кто виноват. Его предмет —
# чтобы красное ствола нельзя было не заметить.
#
# ─────────────────────────────────────────────────────────────────────────────
# ИСХОДОВ ТРИ, И ТРЕТИЙ НЕ ЗАЧИТЫВАЕТСЯ В ЗЕЛЁНОЕ
#
#   0  ствол зелен — события нет и быть не должно;
#   1  ствол КРАСЕН — событие произведено (держатель заведён либо дополнен);
#   2  события НЕ ПРОИЗВЕДЕНО: исходов не подали вовсе, ЛИБО подали, ствол
#      оказался красен, а производитель события отказал.
#
# Код 2 не сливается с 1 намеренно. «Ствол красен, держатель заведён» и «ствол
# красен, завести держателя НЕ УДАЛОСЬ» — разные состояния мира: в первом у
# красного появился читатель, во втором его по-прежнему нет, и знает об этом
# только сам прогон. Слив их в одно, мы объявили бы читателя там, где его нет.
#
# ПОЧЕМУ ЭТА ВЕТВЬ НЕ УМОЗРИТЕЛЬНА. Умолчание прав процесса в этом репозитории —
# `read` (`gh api repos/<репо>/actions/permissions/workflow` →
# `default_workflow_permissions: "read"`). Задание просит `issues: write` явно и
# потому получает его, но каждая политика уровня организации, сужающая права
# токена, отнимает у держателя ровно способность произвести событие — и отнимает
# молча, до первого красного ствола. Поэтому ветвь отказа доказывается
# инъекцией, а не чтением.
#
# Отменённое и снятое по времени задание зелёным НЕ является: вердикта у него
# нет, и «не выполнилось» не вычитается из вердикта и не зачитывается в успех.
# Пропущенное (`skipped`) — зелёное: задание не исполнялось по объявленному
# условию, и это решение рецепта, а не сорванный прогон.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОЧЕМУ ОТДЕЛЬНЫМ ФАЙЛОМ, А НЕ ВЕТКОЙ ВНУТРИ ШАГА
#
# Ветку в шаге нечем доказать инъекцией, а недоказанная ветка сама становится
# тем классом, который она ловит, — формой без содержания. Здесь вход подаётся
# доводами, а производитель события подменяется переменной, поэтому обе стороны
# проверяются за миллисекунды (`--self-test` ниже) — включая ту, где событие
# производиться НЕ ДОЛЖНО.
set -uo pipefail

# reporter — чем производится событие. Умолчание `gh`; самопроверка подставляет
# записывающий дублёр, поэтому провязка доказывается ТЕМ, ЧТО ЕГО ПОЗВАЛИ, а не
# тем, что он ответил «хорошо».
#
# ЧИТАЕТСЯ В МОМЕНТ ВЫЗОВА, А НЕ ПРИ ЗАГРУЗКЕ, и это не стиль. Первая редакция
# брала значение постоянной наверху файла — то есть ДО того, как самопроверка
# подставляла дублёра, — и прогон `--self-test` ушёл к настоящему `gh` и ЗАВЕЛ
# ТРИ НАСТОЯЩИЕ ЗАДАЧИ в трекере. Подделка, до которой можно не дойти, подделкой
# не является: она обязана быть структурно неизбежной, а не назначенной.
reporter() { printf '%s' "${TRUNK_VERDICT_REPORTER:-gh}"; }
# REPO — репозиторий держателя. Пустое означает «взять у окружения прогона».
REPO="${TRUNK_VERDICT_REPO:-}"
# MARKER — по нему держатель НАХОДИТСЯ ПОВТОРНО. Без него каждое красное
# вливание заводило бы новую задачу, и перечень открытых стал бы шумом, который
# перестают читать, — ровно то состояние, из которого мы уходим.
readonly MARKER="ствол красен: вердикт ci на main"
readonly HOLDER_LABELS="P0,area:ci,bug"

# verdict — красен ли ствол по исходам заданий.
#
# Печатает перепись: «ноль красных» обязано быть отличимо от «ноль прочитанного».
verdict() {
    local red=() void=() green=0 skipped=0 r
    for r in "$@"; do
        case "$r" in
            success) green=$((green + 1)) ;;
            skipped) skipped=$((skipped + 1)) ;;
            failure) red+=("$r") ;;
            cancelled|timed_out|"") void+=("${r:-<пусто>}") ;;
            *) void+=("$r") ;;
        esac
    done
    echo "перепись исходов ствола: заданий $#, зелёных $green, пропущенных $skipped," \
         "красных ${#red[@]}, без вердикта ${#void[@]}"
    if [ "${#red[@]}" -eq 0 ] && [ "${#void[@]}" -eq 0 ]; then
        echo "ствол зелен — держателя заводить не из чего"
        return 0
    fi
    echo "СТВОЛ НЕ ЗЕЛЁН: красных ${#red[@]}, без вердикта ${#void[@]}" >&2
    return 1
}

# raise — производит событие: заводит держателя либо дополняет существующего.
#
# Повторное вливание в красный ствол дополняет ОДНОГО держателя, а не заводит
# второго: две задачи об одном предмете расходятся молча, и расходится та,
# которую не читают.
raise() {
    local title="$1" body="$2" args=() found=""
    [ -n "$REPO" ] && args=(-R "$REPO")

    local gh; gh="$(reporter)"
    found="$("$gh" issue list "${args[@]}" --state open --search "$title" \
        --limit 1 --json number -q '.[0].number' 2>/dev/null || true)"
    if [ -n "$found" ] && [ "$found" != "null" ]; then
        "$gh" issue comment "$found" "${args[@]}" --body "$body" || return 2
        echo "держатель дополнен: задача #$found"
        return 0
    fi
    "$gh" issue create "${args[@]}" --title "$title" --label "$HOLDER_LABELS" \
        --body "$body" || return 2
    echo "держатель заведён"
}

# hold — вердикт и, если он не зелен, событие.
#
# Беспредметный вызов отвергается ЗДЕСЬ, а не только нижней развилкой файла:
# самопроверка зовёт `hold` напрямую, и ось «исходов не подали» осталась бы без
# доказательства — то есть ровно в том состоянии, в котором она и была.
hold() {
    local report rc=0
    if [ "$#" -eq 0 ]; then
        echo "исходов заданий не подано — о стволе не сказано НИЧЕГО." >&2
        echo "Это не «зелено», это «вызов не разобран»." >&2
        return 2
    fi
    report="$(verdict "$@" 2>&1)" || rc=$?
    printf '%s\n' "$report"
    [ "$rc" -eq 0 ] && return 0

    local title body
    title="$MARKER (${TRUNK_VERDICT_SHA:-ревизия не названа})"
    body="$(cat <<BODY
Процесс: ${TRUNK_VERDICT_PROCESS:-не назван}

$report

Прогон: ${TRUNK_VERDICT_RUN_URL:-адрес не назван}
Ревизия ствола: ${TRUNK_VERDICT_SHA:-не названа}

Зелёный обязательный контекст запроса слияния этого НЕ ОБЕЩАЛ: проверки идут на
merge-ревизии, где история ветки цела, а здесь вливают схлопыванием — свойства,
зависящие от вхождения коммита в историю, после посадки меняют вердикт на
противоположный. Перечень таких свойств держит ведомость \`vertexLedger\`
(\`internal/check/history_question_vertex_test.go\`), а не этот текст.

Держатель заведён автоматически и сам не закроется: пока он открыт, ствол
считается красным. Закрывать — с артефактом (PR либо SHA починки).
BODY
)"
    raise "$title" "$body" || return 2
    return 1
}

# --- самопроверка: доказательство инъекцией в обе стороны ---------------------
#
# Живёт ФЛАГОМ этого же файла, а не соседним: отдельный файл в перечень шагов
# конвейера не попал бы сам, то есть не исполнялся бы никогда.
if [ "${1:-}" = "--self-test" ]; then
    TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
    # ДУБЛЁР ПРОИЗВОДИТЕЛЯ СОБЫТИЯ — записывающий и заведомо негодный: он ничего
    # не создаёт и отвечает пустотой на поиск. Провязка доказывается ТЕМ, ЧТО ЕГО
    # ПОЗВАЛИ, а не тем, что он ответил «хорошо» (иначе подделка снисходительнее
    # продукта и делает невидимым ровно тот дефект, ради которого её подставляют).
    cat > "$TMP/gh" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$TRUNK_VERDICT_LOG"
case "$*" in *"issue list"*) echo "" ;; esac
exit 0
STUB
    chmod +x "$TMP/gh"
    export TRUNK_VERDICT_REPORTER="$TMP/gh"
    export TRUNK_VERDICT_LOG="$TMP/log"
    # ПРЕДПОСЫЛКА САМОПРОВЕРКИ: производитель события — дублёр, а не настоящий
    # `gh`. Проверяется, а не подразумевается: цена подразумевания измерена —
    # три настоящие задачи в трекере.
    : > "$TRUNK_VERDICT_LOG"
    "$(reporter)" проба-подстановки >/dev/null 2>&1 || true
    if [ "$(reporter)" != "$TMP/gh" ] || ! grep -q 'проба-подстановки' "$TRUNK_VERDICT_LOG"; then
        echo "ПРОВАЛ: производитель события НЕ подменён дублёром (сейчас: $(reporter))." >&2
        echo "Прогон ОТМЕНЁН: он пошёл бы к настоящему трекеру и завёл там задачи." >&2
        exit 2
    fi
    echo "предпосылка: производитель события подменён дублёром ($(reporter)), запись ведётся"

    probes=0; failed=0
    run() { # run <ожидаемый-код> <ожидание-события: yes|no> <имя> <исходы…>
        local want="$1" wantEvent="$2" name="$3"; shift 3
        local got=0 events=0
        probes=$((probes + 1))
        : > "$TRUNK_VERDICT_LOG"
        hold "$@" >/dev/null 2>&1 || got=$?
        events="$(grep -c 'issue create\|issue comment' "$TRUNK_VERDICT_LOG" || true)"
        if [ "$got" -ne "$want" ]; then
            echo "  ПРОВАЛ $name — код ждали $want, получили $got" >&2
            failed=$((failed + 1)); return
        fi
        case "$wantEvent" in
            yes) [ "$events" -ge 1 ] || { echo "  ПРОВАЛ $name — событие НЕ произведено" >&2
                     failed=$((failed + 1)); return; } ;;
            no)  [ "$events" -eq 0 ] || { echo "  ПРОВАЛ $name — событие произведено на зелёном стволе" >&2
                     failed=$((failed + 1)); return; } ;;
        esac
        echo "  ok   $name (код $got, событий $events)"
    }

    echo "=== держатель вердикта ствола: доказательство инъекцией ==="
    # (−) ПОЛОЖИТЕЛЬНЫЙ БЛИЗНЕЦ: без него всё нижеследующее зеленело бы на
    # держателе, который заводит задачу ВСЕГДА.
    run 0 no  "(−) ствол зелен — события нет" success success success
    run 0 no  "(−) пропущенное задание зелёного не отменяет" success skipped success
    # (+) один факт против близнеца: одно задание красно.
    run 1 yes "(+) одно задание красно — событие произведено" success failure success
    run 1 yes "(+) красны все — событие произведено" failure failure
    # (+) ТРЕТЬЯ КАТЕГОРИЯ: вердикта нет, и зелёным она не становится.
    run 1 yes "(+) задание отменено — не зелёное" success cancelled
    run 1 yes "(+) задание снято по времени — не зелёное" success timed_out
    run 1 yes "(+) исход не опознан — не зелёное" success wat
    run 1 yes "(+) исход пуст — не зелёное" success ""
    # (+) БЕСПРЕДМЕТНЫЙ ВЫЗОВ: исходов не подали, и молчание тут означало бы
    # «ствол зелен», чего никто не проверял.
    got=0; hold >/dev/null 2>&1 || got=$?
    probes=$((probes + 1))
    if [ "$got" -ne 2 ]; then
        echo "  ПРОВАЛ (+) исходов не подано — ждали 2, получили $got" >&2
        failed=$((failed + 1))
    else
        echo "  ok   (+) исходов не подано — код 2, о стволе не сказано ничего"
    fi
    # (−) ПОВТОРНОЕ вливание в красный ствол дополняет ОДНОГО держателя.
    cat > "$TMP/gh" <<'STUB2'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$TRUNK_VERDICT_LOG"
case "$*" in *"issue list"*) echo "777" ;; esac
exit 0
STUB2
    chmod +x "$TMP/gh"
    : > "$TRUNK_VERDICT_LOG"
    got=0; hold success failure >/dev/null 2>&1 || got=$?
    probes=$((probes + 1))
    if [ "$got" -eq 1 ] && grep -q 'issue comment 777' "$TRUNK_VERDICT_LOG" \
       && ! grep -q 'issue create' "$TRUNK_VERDICT_LOG"; then
        echo "  ok   (−) держатель найден — дополнен, второй не заведён"
    else
        echo "  ПРОВАЛ (−) существующий держатель не найден: заведён второй" >&2
        failed=$((failed + 1))
    fi

    # ────────────────────────────────────────────────────────────────────────
    # (+) ПРОИЗВОДИТЕЛЬ СОБЫТИЯ ОТКАЗАЛ — «красен, но читателя нет» ≠ «заведён».
    #
    # Единственная ветвь держателя, которую прошлая редакция НЕ наблюдала: она
    # доходит до настоящего трекера, и проверять её живым `gh` значило бы завести
    # ложную запись `P0` о красном стволе при зелёном. Подставной производитель
    # снимает эту цену целиком: отказ воспроизводится точно, а трекер не тронут.
    #
    # Ветвь не умозрительна: умолчание прав процесса здесь — `read`, и всякое
    # сужение политики отнимает у держателя ровно способность писать задачи.
    cat > "$TMP/gh" <<'STUB3'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$TRUNK_VERDICT_LOG"
case "$*" in
    *"issue list"*) echo "" ;;
    *"issue create"*|*"issue comment"*) echo "отказано: Resource not accessible by integration" >&2; exit 1 ;;
esac
exit 0
STUB3
    chmod +x "$TMP/gh"

    : > "$TRUNK_VERDICT_LOG"
    got=0; hold success failure >/dev/null 2>&1 || got=$?
    probes=$((probes + 1))
    if [ "$got" -eq 2 ] && grep -q 'issue create' "$TRUNK_VERDICT_LOG"; then
        echo "  ok   (+) производитель отказал на заведении — код 2, не 1: читателя НЕ появилось"
    else
        echo "  ПРОВАЛ (+) отказ заведения: ждали код 2 при состоявшейся попытке, получили $got" >&2
        failed=$((failed + 1))
    fi

    # То же на ВТОРОМ вливании в красный ствол: держатель найден, дополнить его
    # не удалось. Ветвь отдельная — она идёт через `issue comment`, а не `create`.
    cat > "$TMP/gh" <<'STUB4'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$TRUNK_VERDICT_LOG"
case "$*" in
    *"issue list"*) echo "777" ;;
    *"issue comment"*) echo "отказано: Resource not accessible by integration" >&2; exit 1 ;;
esac
exit 0
STUB4
    chmod +x "$TMP/gh"

    : > "$TRUNK_VERDICT_LOG"
    got=0; hold success failure >/dev/null 2>&1 || got=$?
    probes=$((probes + 1))
    if [ "$got" -eq 2 ] && grep -q 'issue comment 777' "$TRUNK_VERDICT_LOG"; then
        echo "  ok   (+) производитель отказал на дополнении — код 2, не 1"
    else
        echo "  ПРОВАЛ (+) отказ дополнения: ждали код 2 при состоявшейся попытке, получили $got" >&2
        failed=$((failed + 1))
    fi

    # (−) ЗАКОННЫЙ БЛИЗНЕЦ отказа: производитель отказал БЫ, но ствол ЗЕЛЁН —
    # значит его не зовут вовсе. Без этой половины обе пробы выше зеленели бы на
    # держателе, который ходит в трекер на каждом вливании и падает кодом 2
    # всегда: «красен» стало бы неотличимо от «не смог спросить».
    : > "$TRUNK_VERDICT_LOG"
    got=0; hold success success skipped >/dev/null 2>&1 || got=$?
    probes=$((probes + 1))
    if [ "$got" -eq 0 ] && ! grep -q 'issue create\|issue comment\|issue list' "$TRUNK_VERDICT_LOG"; then
        echo "  ok   (−) ствол зелен — производителя не звали, отказать было негде"
    else
        echo "  ПРОВАЛ (−) на зелёном стволе производитель события ВСЁ РАВНО позван (код $got)" >&2
        failed=$((failed + 1))
    fi

    echo
    echo "trunk-verdict-holder --self-test: проб исполнено $probes, провалов $failed"
    [ "$probes" -eq 0 ] && { echo "ПРОВАЛ: ни одной пробы не исполнено" >&2; exit 2; }
    [ "$failed" -gt 0 ] && exit 1
    exit 0
fi

if [ "$#" -eq 0 ]; then
    echo "нужен хотя бы один довод: исход задания (success|failure|skipped|cancelled|…)" >&2
    echo "о стволе не сказано НИЧЕГО: это не «зелено», это «вызов не разобран»" >&2
    exit 2
fi
hold "$@"
